window.kbPageData["views/entry/k-d413fa9da91efecd"] = {"key":"entry/k-d413fa9da91efecd","state":{"route":"entry/k-d413fa9da91efecd"},"node":{"id":"k-d413fa9da91efecd","mode":"k","title":"否定必要条件的推理","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["否定必要条件可推出其对应命题不成立"],"qs":["江苏 2023 B类 行测#105"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"“只有P，才Q”表示P是Q成立的必要条件，即Q成立必有P成立。因此，P不成立时，可以推出Q也不成立。","review":{"definition":"“只有P，才Q”表示P是Q成立的必要条件，即Q成立必有P成立。因此，P不成立时，可以推出Q也不成立。","explanation":"丙若不点清蒸鲈鱼，按条件（4）也不能点芹菜肉丝和毛豆仔鸡，只剩一道菜，无法点满两道。因此丙点清蒸鲈鱼，乙和丁也点。由于四人不能都点同一道菜，甲不点清蒸鲈鱼，进而由条件（1）推出丁不点芹菜肉丝。乙按条件（3）点毛豆仔鸡。四人的两道菜组合互不相同，丁只能给清蒸鲈鱼搭配糖醋排骨，丙则只能搭配芹菜肉丝，因此选C。","references":[],"evidence":"只有甲点清蒸鲈鱼，丁才点芹菜肉丝","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#105":{"paper":"江苏 2023 B类 行测","n":105,"mod":"判断推理","src":["22262c34d18cd68fbee4.pdf",21],"asrc":["b08f2713d73015eac675.pdf",34],"card":"0f2b207cd1d3392a15df8680","links":[{"id":"k-d413fa9da91efecd","role":"解题依据","why":"甲点清蒸鲈鱼是丁点芹菜肉丝的必要条件，据甲没点鲈鱼可排除丁点芹菜肉丝。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d413fa9da91efecd":[["江苏 2023 B类 行测#105"]]}};
